import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// A [ShellJob] for the in-process sandbox shells ([MemoryShell] on web,
/// [WasiSandboxShell] on mobile): no OS process exists, so the "job" is the
/// script's Future running on a job-local shell clone; its output streams
/// into the log file through the injected [logWriter] (a host file sink for
/// the WASI shell, the memory FS for the web shell).
final class SandboxShellJob implements ShellJob {
  /// Creates a job; [_closeLog] flushes/closes the log writer at completion.
  SandboxShellJob({
    required this.id,
    required this.command,
    required this.logPath,
    required this._logWriter,
    this._closeLog,
  });

  final FutureOr<void> Function(String chunk) _logWriter;
  final FutureOr<void> Function()? _closeLog;
  final _cancelSource = CancelTokenSource();
  final _settled = Completer<void>();
  Future<void> _writeChain = Future<void>.value();
  int? _exitCode;
  String? _stopReason;

  @override
  final String id;

  @override
  final String command;

  @override
  final String logPath;
  @override

  /// No host process on the sandboxed shell: the sweep has nothing to
  /// record for web/WASI jobs.
  int? get pid => null;

  /// The token the job's script runs under; [stop] cancels it. Callers wire
  /// an outer abort token to [stop] (the job never shares the caller's token
  /// directly so [stop] stays distinguishable from a plain abort).
  CancelToken get cancelToken => _cancelSource.token;

  @override
  bool get isRunning => _exitCode == null;

  @override
  int? get exitCode => _exitCode;

  @override
  String? get stopReason => _stopReason;

  @override
  Future<void> get settled => _settled.future;

  /// No live output stream: sandbox jobs stream into the log file only
  /// (no OS process to attach to).
  @override
  Stream<String> get output => const Stream.empty();

  /// No OS process: a sandbox job cannot accept live stdin writes
  /// (issue #367 E3 - the ask stays visible in the job log, documented).
  @override
  bool writeStdin(String data) => false;

  /// Appends one output chunk to the log, serialized so concurrent
  /// stdout/stderr chunks keep their arrival order. A failing log writer
  /// must not poison the chain — completeWith drains it before settling
  /// (issue #925: a broken log must never kill the host or hang the job).
  void writeLog(String chunk) {
    _writeChain = _writeChain
        .then((_) => _logWriter(chunk))
        .catchError((Object _) {});
  }

  /// Completes the job from the script's exec result (called by the owning
  /// shell's detached run). Idempotent; the first completion wins.
  Future<void> completeWith(
    Result<ShellExecResult, ExecutionError> result,
  ) async {
    if (_exitCode != null) return;
    if (result.isErr) {
      final error = result.errorOrNull!;
      if (error.code != ExecutionErrorCode.aborted) {
        // Surface backend failures in the log, not just the exit code.
        writeLog('[job error: $error]\n');
      }
    }
    await _writeChain;
    await _closeLog?.call();
    if (result.isOk) {
      _exitCode = result.valueOrNull!.exitCode;
    } else {
      final error = result.errorOrNull!;
      _exitCode = switch (error.code) {
        ExecutionErrorCode.aborted => 143,
        ExecutionErrorCode.timeout => 124,
        _ => 1,
      };
      if (error.code == ExecutionErrorCode.aborted) {
        _stopReason ??= 'cancelled';
      } else if (error.code == ExecutionErrorCode.timeout) {
        _stopReason ??= 'timeout';
      }
    }
    _settled.complete();
  }

  @override
  Future<void> stop() async {
    // A stop landing after completion must not rewrite the outcome.
    if (_exitCode == null) _stopReason ??= 'stopped';
    _cancelSource.cancel();
  }
}

import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:test/test.dart';

void main() {
  late Directory tempDir;
  late LocalExecutionEnv env;

  setUp(() {
    tempDir = Directory.systemTemp.createTempSync('shell-job-test-');
    env = LocalExecutionEnv(cwd: tempDir.path);
  });

  tearDown(() {
    if (tempDir.existsSync()) tempDir.deleteSync(recursive: true);
  });

  group('BackgroundShell (local)', () {
    test('a job runs detached, writes its log, and settles', () async {
      final started = await env.startShellJob(
        'echo hello && echo err >&2',
        id: 'sh-1',
        logPath: '${tempDir.path}/sh-1.log',
      );
      expect(started.isOk, isTrue);
      final job = started.valueOrNull!;
      expect(job.isRunning, isTrue);
      await job.settled;
      expect(job.exitCode, 0);
      expect(job.stopReason, isNull);
      final log = File(job.logPath).readAsStringSync();
      expect(log, contains('hello'));
      expect(log, contains('err'));
    });

    test('stop terminates a long-running job', () async {
      final started = await env.startShellJob(
        'sleep 60',
        id: 'sh-2',
        logPath: '${tempDir.path}/sh-2.log',
      );
      final job = started.valueOrNull!;
      expect(job.isRunning, isTrue);
      await job.stop();
      await job.settled;
      expect(job.isRunning, isFalse);
      expect(job.exitCode, isNot(0));
      expect(job.stopReason, 'stopped');
    });

    test('the timeout kills the job and records the reason', () async {
      final started = await env.startShellJob(
        'sleep 60',
        id: 'sh-3',
        logPath: '${tempDir.path}/sh-3.log',
        options: const ShellExecOptions(timeout: Duration(milliseconds: 300)),
      );
      final job = started.valueOrNull!;
      await job.settled;
      expect(job.isRunning, isFalse);
      expect(job.stopReason, 'timeout');
    });

    test('the cancel token kills the job and records the reason', () async {
      final source = CancelTokenSource();
      final started = await env.startShellJob(
        'sleep 60',
        id: 'sh-4',
        logPath: '${tempDir.path}/sh-4.log',
        options: ShellExecOptions(cancelToken: source.token),
      );
      final job = started.valueOrNull!;
      source.cancel();
      await job.settled;
      expect(job.stopReason, 'cancelled');
    });

    test('live stdin: the pipe stays open until the process ends and a '
        'write reaches it (issue #367)', () async {
      final channel = LiveStdinChannel();
      final started = await env.startShellJob(
        'read line; echo "got:\$line"',
        id: 'sh-5',
        logPath: '${tempDir.path}/sh-5.log',
        options: ShellExecOptions(liveStdin: channel),
      );
      final job = started.valueOrNull!;
      expect(channel.isBound, isTrue);
      // The pipe is still open: the stdin-reader has not seen EOF and
      // keeps waiting for the answer.
      await Future<void>.delayed(const Duration(milliseconds: 300));
      expect(job.isRunning, isTrue);
      expect(channel.write('s3cret\n'), isTrue);
      await job.settled;
      expect(job.exitCode, 0);
      final log = File(job.logPath).readAsStringSync();
      expect(log, contains('got:s3cret'));
      // The process is gone: a late write fails cleanly, never throws.
      expect(channel.write('late\n'), isFalse);
    });

    test(
      'without a live channel stdin closes at start (ripgrep safety)',
      () async {
        final started = await env.startShellJob(
          'read line; echo "got:\$line"',
          id: 'sh-6',
          logPath: '${tempDir.path}/sh-6.log',
        );
        final job = started.valueOrNull!;
        await job.settled;
        expect(job.exitCode, 0);
      },
    );

    test('an unwritable job log fails cleanly instead of crashing with an '
        'unhandled error (issue #925)', () async {
      // The log path's parent is a regular file, so the open fails with
      // ENOTDIR — the same FileSystemException class as the ticket's
      // ENOSPC. Pre-fix the open ran unowned inside `File.openWrite` and
      // the error escaped to the root-zone handler (fatal for fa) while
      // the job never settled.
      final blocker = File('${tempDir.path}/bash_jobs')
        ..writeAsStringSync('not a directory\n');
      final started = await env.startShellJob(
        'echo hi',
        id: 'sh-7',
        logPath: '${blocker.path}/sh-7.log',
      );
      expect(started.isErr, isTrue);
      expect(
        started.errorOrNull!.message,
        contains('cannot open job log file'),
      );
      // Settle the event loop: a broken implementation surfaces its
      // unhandled write error here and fails the whole suite.
      await Future<void>.delayed(const Duration(milliseconds: 300));
    });
  });
  group('job stop kills the whole process tree (issue #517)', () {
    // Per-run fractional seconds keep the ps scan unique to this run, and
    // a force-reap teardown keeps even a RED run from leaking sleepers.
    String token(int n) =>
        '517.$n${DateTime.now().microsecondsSinceEpoch % 100000}';

    test('stop kills a grandchild forked by the job (AC1)', () async {
      final secs = token(1);
      addTearDown(() => Process.run('pkill', ['-f', 'sleep $secs']));
      final started = await env.startShellJob(
        'sleep $secs & wait',
        id: 'sh-517a',
        logPath: '${tempDir.path}/sh-517a.log',
      );
      final job = started.valueOrNull!;
      await Future<void>.delayed(const Duration(milliseconds: 300));
      // Fixture sanity: the grandchild is alive before the stop.
      expect(await _liveProcesses('sleep $secs'), hasLength(1));
      await job.stop();
      await job.settled;
      await Future<void>.delayed(const Duration(milliseconds: 700));
      expect(await _liveProcesses('sleep $secs'), isEmpty);
    });

