Future<Result<ShellJob, ExecutionError>> startShellJob(
  String command, {
  required String id,
  required String logPath,
  ShellExecOptions? options,
}) async {
  final token = [REDACTED:Sensitive Value];
  if (token != null && token.isCancelled) {
    return const Err(ExecutionError(ExecutionErrorCode.aborted, 'aborted'));
  }
  final logOpen = await _openJobLog(logPath);
  if (logOpen.isErr) return Err(logOpen.errorOrNull!);
  return Ok(
    _wireJob(
      command,
      id: id,
      logPath: logPath,
      logFile: logOpen.valueOrNull!,
      token: [REDACTED:Sensitive Value],
      options: options,
    ),
  );
}

/// Issue #925: same guarded eager open as LocalShell.startShellJob.
/// `File.openWrite` under a try/catch is false safety — the open starts
/// eagerly but its failure is async and unowned, so open-class errors
/// (missing dir, permissions, ENOSPC) escaped to the zone mid-job.
Future<Result<io.RandomAccessFile, ExecutionError>> _openJobLog(
  String logPath,
) async {
  try {
    return Ok(await io.File(logPath).open(mode: io.FileMode.append));
  } on Object catch (error) {
    return Err(
      ExecutionError(
        ExecutionErrorCode.spawnError,
        'cannot open job log file $logPath: $error',
        cause: error,
      ),
    );
  }
}

/// Builds the job over the opened log, wires the cancel token, and
/// detaches the script run. SandboxShellJob serializes writers
/// (RandomAccessFile allows one op at a time) and consumes write errors.
SandboxShellJob _wireJob(
  String command, {
  required String id,
  required String logPath,
  required io.RandomAccessFile logFile,
  required CancelToken? token,
  required ShellExecOptions? options,
}) {
  final job = SandboxShellJob(
    id: id,
    command: command,
    logPath: logPath,
    logWriter: logFile.writeString,
    closeLog: () async {
      // Issue #925: a broken log sink must not break the settle path.
      try {
        await logFile.flush();
      } on Object {}
      try {
        await logFile.close();
      } on Object {}
    },
  );
  // An outer abort stops the job too (same contract as the local shell).
  token?.onCancel.then((_) => job.stop());
  unawaited(
    _forJob()
        .exec(
          command,
          options: ShellExecOptions(
            cwd: options?.cwd,
            env: options?.env,
            timeout: options?.timeout,
            cancelToken: job.cancelToken,
            onStdout: job.writeLog,
            onStderr: job.writeLog,
          ),
        )
        .then(job.completeWith),
  );
  return job;
}

/// A job-local clone: shares the WASM modules, HTTP client, and sandbox
/// host path, owns the mutable interpreter state (cwd, shell vars, output
/// capture stack), so a detached job never clobbers the foreground shell
/// or a sibling job.
WasiSandboxShell _forJob() {
  final clone = WasiSandboxShell(
    coreutils: coreutils,
    rg: rg,
    find: find,
    sed: sed,
    awk: awk,

    // lifetime so a mid-run password ask can be answered; otherwise it
    // closes right after start — background jobs are not interactive
    // beyond this.
    final liveStdin = options?.liveStdin;
    if (liveStdin != null) {
      liveStdin.bind(process.stdin.write);
    }
    if (options?.stdinData != null) {
      try {
        process.stdin.write(options!.stdinData);
        await process.stdin.flush();
      } on Object {
        // Process already gone — the settle path reports the real status.
      }
    }
    if (liveStdin == null) unawaited(process.stdin.close());
    final RandomAccessFile logSink;
    try {
      // Issue #925: open the log eagerly and guard it HERE. `File.openWrite`
      // starts its open lazily-but-eagerly with no owner for the failure —
      // an error (missing directory, permissions, ENOSPC) surfaced as an
      // unlistened future and reached the root-zone handler, killing the
      // whole fa process. An awaited open turns every open-class failure
      // into this clean Err instead.
      logSink = await File(logPath).open(mode: FileMode.append);
    } on Object catch (error) {
      process.kill();
      return Err(
        ExecutionError(
          ExecutionErrorCode.spawnError,
          'cannot open job log file $logPath: $error',
          cause: error,
        ),
