    }
    return Ok(
      _LocalShellJob(
        id: id,
        command: command,
        logPath: logPath,
        process: process,
        logSink: logSink,
        timeout: options?.timeout,
        token: [REDACTED:Sensitive Value],
        ownGroup: ownGroup,
      ),
